C=[2,5,0,5]
def transform(g):
    g=[r[:] for r in g]
    H,W=len(g),len(g[0])
    rows=[i for i in range(H) if 5 in g[i]]
    cols=[j for j in range(W) if any(g[i][j]==5 for i in range(len(g)))]
    r0,r1,c0,c1=min(rows),max(rows),min(cols),max(cols)
    h,w=r1-r0+1,c1-c0+1
    D=(min(h,w)-1)//2  # max depth (center single cell when h,w odd)
    for i in range(r0+1,r1):
        for j in range(c0+1,c1):
            d=min(i-r0,r1-i,j-c0,c1-j)
            if h%2==1 and w%2==1 and d==D and D%8==4:
                g[i][j]=0   # center of square with D=4 mod 8 stays 0
            else:
                g[i][j]=C[(d-1)%4]
    return g
